            {
              "texto": "Conformidad normativa",
              "esCorrecta": true,
              "justificacion": "Se ajusta para ser aceptado por el grupo."
            },
            {
              "texto": "Disonancia cognitiva",
              "esCorrecta": false,
              "justificacion": "Describe un conflicto interno entre creencias."
            },
            {
              "texto": "Efecto halo",
              "esCorrecta": false,
              "justificacion": "Es un sesgo de percepción, no de presión social."
            }
          ]
        },
        {
          "enunciado": "¿Qué acción favorece una decisión ética del grupo?",
          "criterio": "aplicacion",
          "opciones": [
            {
              "texto": "Proponer una discusión abierta con evidencias",
              "esCorrecta": true,
              "justificacion": "Reduce la ignorancia pluralista."
            },
            {
              "texto": "Votar de inmediato sin discutir",
              "esCorrecta": false,
              "justificacion": "Refuerza la presión de la mayoría."
            },
            {
              "texto": "Aceptar la opinión del líder",
              "esCorrecta": false,
